const notificationKey='jarvis-notifications-v1';
let notificationHistory=[];
try{const saved=JSON.parse(localStorage.getItem(notificationKey)||'[]');if(Array.isArray(saved))notificationHistory=saved.filter(n=>n&&typeof n.id==='string'&&typeof n.title==='string'&&typeof n.message==='string'&&Number.isFinite(n.createdAt)).slice(0,100).map(n=>({...n,seen:n.seen===true,example:n.example===true}));}catch{}
let notificationInboxOpen=false,notificationFilter='all',notificationStorageError=false;
