function saveNotificationHistory(){try{localStorage.setItem(notificationKey,JSON.stringify(notificationHistory));notificationStorageError=false;}catch{notificationStorageError=true;}}
function addNotification(entry){if(!entry.example&&!entry.topPick)return;notificationHistory.unshift(entry);notificationHistory=notificationHistory.slice(0,100);saveNotificationHistory();signalNotices.queue.push(entry.id);renderNotificationInbox();showNextSignalNotice();}
function ensureNotificationInbox(){if($('#notification-center'))return;const center=document.createElement('div');center.id='notification-center';document.body.append(center);renderNotificationInbox();}
function renderNotificationInbox(){
 if(!$('#notification-center')){ensureNotificationInbox();return;}
 const unseen=notificationHistory.filter(n=>!n.seen).length,items=notificationHistory.filter(n=>notificationFilter==='all'||!n.seen);
 $('#notification-center').innerHTML=`<button type="button" id="notification-bell" aria-label="Notifications, ${unseen} unseen" aria-expanded="${notificationInboxOpen}" aria-controls="notification-inbox" data-action="toggle-notification-inbox"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>${unseen?`<span class="notification-count">${unseen>99?'99+':unseen}</span>`:''}</button><section id="notification-inbox" role="region" aria-label="Notification inbox" ${notificationInboxOpen?'':'hidden'}><div class="notification-inbox-head"><h2>Notifications <small>${unseen} unseen</small></h2><button type="button" class="small" data-action="close-notification-inbox" aria-label="Close notification inbox">×</button></div><div class="notification-inbox-controls"><label>Show <select name="notification-filter"><option value="all" ${notificationFilter==='all'?'selected':''}>All notifications</option><option value="unseen" ${notificationFilter==='unseen'?'selected':''}>Unseen only</option></select></label><button type="button" class="small" data-action="notifications-seen" ${unseen?'':'disabled'}>Mark all seen</button></div><p class="notification-history-note">Last 100 notifications on this browser. Status and score reflect when received.${notificationStorageError?' Browser storage unavailable; changes last for this page session.':''}</p><div class="notification-inbox-list">${items.length?items.map(n=>`<article class="notification-item ${n.seen?'is-seen':'is-unseen'}"><div class="notification-item-heading"><strong>${esc(notificationCategory(n))}</strong>${badge(n.example?'EXAMPLE':n.seen?'SEEN':'UNSEEN',n.example?'warn':n.seen?'':'cyan')}</div><p><strong>${esc(n.title)}</strong></p><p>${esc(n.message)}</p>${n.example?'<p class="note">Example only · not a market signal</p>':`<div class="notification-item-meta">${statusBadge(n.status)}<span>${n.probability==null?'Profit estimate unavailable':num(n.probability*100,0)+'% estimated win percent'}</span></div>`}<small>${date(n.createdAt)}</small><div class="notification-item-actions"><button type="button" class="small" data-notification-toggle="${esc(n.id)}">Mark ${n.seen?'unseen':'seen'}</button>${!n.example?`<button type="button" class="small" data-notification-view="${esc(n.id)}">View current setup</button>`:''}</div></article>`).join(''):'<div class="notification-empty">'+(notificationFilter==='unseen'?'You’re all caught up.':'No notifications yet. Send an example from Settings to try it.')+'</div>'}</div></section>`;
}
function toggleNotificationSeen(id){const n=notificationHistory.find(n=>n.id===id);if(!n)return;n.seen=!n.seen;saveNotificationHistory();renderNotificationInbox();const button=[...document.querySelectorAll('[data-notification-toggle]')].find(el=>el.dataset.notificationToggle===id);(button||$('#notification-bell'))?.focus();}
function closeNotificationInbox(){notificationInboxOpen=false;renderNotificationInbox();$('#notification-bell')?.focus();showNextSignalNotice();}
function dismissSignalNotice(){clearTimeout(signalNotices.timer);signalNotices.timer=null;$('#signal-notifications')?.replaceChildren();showNextSignalNotice();}
function showNextSignalNotice(){
 if(signalNotices.timer||document.hidden||notificationInboxOpen||!signalNotices.queue.length)return;
 let entry;while(signalNotices.queue.length&&!entry){const id=signalNotices.queue.shift();entry=notificationHistory.find(n=>n.id===id);}if(!entry)return;
 let host=$('#signal-notifications');if(!host){host=document.createElement('div');host.id='signal-notifications';host.setAttribute('role','status');host.setAttribute('aria-live','polite');host.setAttribute('aria-atomic','true');document.body.append(host);}
 const card=document.createElement('div');card.className='signal-notification';
 card.innerHTML=`<div class="signal-notification-top"><span class="signal-notification-category">${esc(notificationCategory(entry))}</span><button type="button" class="small" aria-label="Dismiss signal notification" data-dismiss-signal-notice>×</button></div><button type="button" class="signal-notification-content" data-notification-open="${esc(entry.id)}"><strong>${esc(entry.title)}</strong><span>${esc(entry.message)}</span>${entry.example?'<small>Example only · not a market signal</small>':`<span class="signal-notification-meta">${statusBadge(entry.status)}<span>${entry.probability==null?'Profit estimate unavailable':num(entry.probability*100,0)+'% estimated win percent'}</span></span>`}<small>Open notification inbox →</small></button>${!entry.example&&state.signals.some(s=>s.id===entry.signalId)?`<div class="form-actions"><button data-log-signal="${esc(entry.signalId)}" data-decision="taken">Taken · log fill</button><button data-log-signal="${esc(entry.signalId)}" data-decision="skipped">Skipped · log reason</button></div>`:''}<div class="signal-notification-track" aria-hidden="true"><div class="signal-notification-countdown"></div></div>`;
 host.replaceChildren(card);signalNotices.timer=setTimeout(dismissSignalNotice,3000);
}
