function stats(market){const r=state.risk,s=state.settings,plans=liveActionable(radarSignals(market),market),action=groupSignalCards(plans).length;return `<div class="stats" data-live-stats><div class="stat"><div class="stat-label">Market focus</div><div class="stat-value">${state.session.stocks?'US equities':'Crypto'} <small>${state.session.stocks?'RTH':'24 / 7'}</small></div><div class="stat-note">${esc(state.session.label)}</div></div><div class="stat"><div class="stat-label">Actionable signals</div><div class="stat-value cyan">${action}<small>ready now</small></div><div class="stat-note">${plans.length} confirmed plan${plans.length===1?'':'s'} · ${market==='stocks'?'stocks & options':market==='crypto'?'crypto':'all markets'}<br>Matches radar filters · current quotes & entry window</div></div><div class="stat"><div class="stat-label">Daily trade allowance</div><div class="stat-value">${r.used}<small>of ${s.maxTrades} used</small></div><div class="stat-note">${r.remaining} remaining across both markets</div><div class="risk-track">${Array.from({length:Math.min(s.maxTrades,10)},(_,i)=>`<i class="${i<r.used?'used':''}"></i>`).join('')}</div></div><div class="stat"><div class="stat-label">Consecutive losses</div><div class="stat-value ${r.locked?'red':''}">${r.streak}<small>of ${s.maxLosses} losses</small></div><div class="stat-note ${r.locked?'red':''}">${r.locked?'Entries locked until daily reset':'Daily loss guard active'}</div></div><div class="stat"><div class="stat-label">Realized P/L today</div><div class="stat-value ${r.pnl>0?'live':r.pnl<0?'red':''}">${money(r.pnl)}</div><div class="stat-note">Manual journal · ${r.wins}W / ${r.losses}L</div></div></div>`;}
