 const sig=state.signals.find(s=>s.id===chartSignal&&s.symbol===a.symbol&&s.tf===chartTF)||state.signals.find(s=>s.symbol===a.symbol&&s.tf===chartTF),levels=sig?[['Entry',sig.price,'#68d8ed'],['Stop',sig.stop,'#e6a75f'],['Target',sig.target,'#aaa0ff']]:[];
 const W=900,H=330,L=12,R=100,T=28,B=30,high=Math.max(...bars.map(b=>b.high),...levels.map(x=>x[1]).filter(Number.isFinite)),low=Math.min(...bars.map(b=>b.low),...levels.map(x=>x[1]).filter(Number.isFinite)),pad=(high-low)*.12||1,min=low-pad,max=high+pad,step=(W-L-R)/bars.length,x=i=>L+(i+.5)*step,y=v=>T+(max-v)/(max-min)*(H-T-B),maxVol=Math.max(1,...bars.map(b=>b.volume));let out='';
 for(let i=0;i<5;i++){const value=min+(max-min)*i/4;out+=`<line x1="${L}" y1="${y(value)}" x2="800" y2="${y(value)}" stroke="#2b3946" stroke-dasharray="2 5"/><text x="806" y="${y(value)+4}" fill="#9cafc1" font-size="11">${num(value,value<10?4:2)}</text>`;}
