document.addEventListener('pointermove',e=>{const svg=e.target.closest?.('#interactive-price');if(!svg||!chartView)return;const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const local=p.matrixTransform(svg.getScreenCTM().inverse());inspectCandle(Math.floor((local.x-12)/788*chartView.bars.length));});
