function watchlist(market){const rows=market==='stocks'?state.settings.stocks:market==='crypto'?state.settings.crypto:[...state.settings.crypto,...state.settings.stocks.slice(0,3)];return '<section class="panel"><div class="panel-head"><h2>Watchlist</h2><div class="watch-actions"><span class="mini">'+rows.length+' ASSETS</span>'+(market!=='crypto'?'<button class="small" data-action="edit-watchlist">Edit watchlist</button>':'')+'</div></div>'+rows.map(symbol=>{const a=state.assets.find(x=>x.symbol===symbol),q=a?.quote,stale=!quoteFresh(q);return '<button class="watch-row '+(symbol===selected?'selected':'')+'" data-symbol="'+esc(symbol)+'"><div class="watch-icon">'+(symbol==='BTC-USD'?'₿':symbol==='ETH-USD'?'Ξ':esc(symbol.slice(0,2)))+'</div><div><strong>'+esc(symbol.replace('-USD',''))+'</strong><small>'+(symbol.includes('-')?'Spot · USD':'US equity')+'</small></div><div class="watch-numbers mono">'+money(q?.price)+'<small class="'+(stale?'amber':q.change>=0?'up':'down')+'">'+(a?.snapshot?(stale?'STALE SNAPSHOT':'SNAPSHOT'):stale?a?.replay?'REPLAY DATA':q?'STALE QUOTE':'NO QUOTE':(q.change>=0?'+':'')+num(q.change)+'%')+'</small></div>'+(!symbol.includes('-')?'<div class="watch-trend">'+stockDirection(symbol)+'</div>':'')+'</button>';}).join('')+'</section>';}
