function leverageDetail(s){const p=leveragePlan(s);return '<section id="leverage-detail" data-plan-signal="'+esc(s.id)+'" class="leverage-detail"><h2>Crypto leverage planning</h2><div class="leverage-summary"><div><small>PLANNING LEVERAGE</small><strong class="'+(p.suggested?'cyan':'amber')+'">'+(p.suggested?p.suggested+'×':'No entry')+'</strong><p>'+esc(p.label)+'</p></div><div><small>RULE CHECKS</small><strong>'+esc(p.confidence?.band)+'</strong><p>Profit chance is shown separately by the trained model.</p></div></div><p class="section-note">'+esc(p.reason)+'</p><p class="note">Fixed risk-sized position: '+num(p.contracts,0)+' contracts · '+money(p.notional)+' notional · '+money(p.plannedRisk)+' planned stop loss including modeled costs · '+num(p.stopPercent,2)+'% stop distance'+(p.productId?' · '+esc(p.productId):'')+'.</p>'+(!p.contracts&&p.minimumContractRisk!=null?'<p class="note amber">Estimated minimum-contract risk: '+money(p.minimumContractRisk)+' against your '+money(state.settings.risk)+' planned-loss budget. Zero contracts means the planner cannot size a position within the current rules.</p>':'')+'<div class="table-wrap"><table><thead><tr><th>LEVERAGE</th><th>MARGIN</th><th>PLANNED STOP LOSS</th><th>LOSS / MARGIN</th><th>MARGIN CHECK</th></tr></thead><tbody>'+(p.levels?.length?p.levels:Array.from({length:10},(_,i)=>({leverage:i+1,margin:null,lossOnMarginPct:null,allowed:false,reason:p.reason}))).map(l=>'<tr><td>'+l.leverage+'×</td><td class="mono">'+money(l.margin)+'</td><td class="mono">'+money(p.plannedRisk)+'</td><td>'+num(l.lossOnMarginPct,2)+'%</td><td><span class="'+(l.allowed?'cyan':'amber')+'">'+(l.allowed?'Within margin rules':'Blocked')+'</span><div class="note">'+esc(l.reason)+'</div></td></tr>').join('')+'</tbody></table></div><p class="note">The position size stays fixed across 1×–10×; leverage changes required margin and the loss as a share of margin. Higher leverage does not improve setup confidence. Planned risk is an estimate, not a guaranteed loss limit; gaps, fees and slippage can exceed it.</p><p class="note">'+esc(p.basisNote)+'</p><p class="note amber">Account eligibility and futures candle confirmation are not verified. This planning table does not authorize or execute a trade.</p></section>';}
function derivativesSummary(){const d=state.derivatives||{},now=networkError?Date.now():state.now,items=['BTC-USD','ETH-USD'].map(symbol=>{const p=d.products?.[symbol],metadata=!!(!networkError&&!d.error&&p?.fetchedAt&&now-p.fetchedAt>=-5000&&now-p.fetchedAt<=90000&&p.productId&&p.unitSize>0&&p.minContracts>0&&p.contractIncrement>0&&p.priceTick>0&&[p.intraday?.long,p.intraday?.short,p.overnight?.long,p.overnight?.short].every(x=>x>0&&x<=1)),fresh=!!(metadata&&p.quote?.price>0&&p.quote.time&&now-p.quote.time>=-5000&&now-p.quote.time<=30000);return {symbol,p,metadata,fresh};});return {d,items,healthy:items.every(x=>x.fresh&&x.p.sessionOpen)};}
function derivativesPanel(){const {d,items,healthy}=derivativesSummary();return '<section class="panel"><div class="panel-head"><div><h2>Crypto derivatives data</h2><p class="note">Coinbase US nano perpetual-style contracts · public market data</p></div>'+badge(healthy?'DATA FRESH':'CHECK DATA',healthy?'good':'warn')+'</div><div class="panel-body derivatives-status">'+(d.error?'<div class="notice">'+esc(d.error)+'</div>':'')+items.map(({symbol,p,metadata,fresh})=>'<div class="derivatives-product"><div class="rule-title"><strong>'+esc(symbol)+' · '+esc(p?.name||p?.productId||'Awaiting contract')+'</strong>'+badge(!p?'LOADING':!p.sessionOpen?'SESSION CLOSED':fresh?'QUOTE FRESH':'QUOTE STALE',p?.sessionOpen&&fresh?'good':'warn')+'</div><p class="note">Contract specification & published margin rules: <span class="'+(metadata?'live':'amber')+'">'+(metadata?'verified public data':'unavailable / stale')+'</span>'+ (p?' · '+num(p.unitSize,8)+' units per contract · '+money(p.quote?.price)+' · quote '+time(p.quote?.time):'')+'</p>'+(p?'<p class="note">Metadata '+time(p.fetchedAt)+' · intraday margin long / short '+num(p.intraday?.long==null?null:p.intraday.long*100)+'% / '+num(p.intraday?.short==null?null:p.intraday.short*100)+'% · overnight '+num(p.overnight?.long==null?null:p.overnight.long*100)+'% / '+num(p.overnight?.short==null?null:p.overnight.short*100)+'%</p>':'')+'</div>').join('')+'<p class="note">Funding: '+items.map(({symbol,p})=>esc(symbol)+' '+(p?.fundingRate==null?'unavailable':num(p.fundingRate*100,5)+'%')+' · '+date(p?.fundingTime)).join('; ')+'. Open interest: unavailable from this connected US feed. Liquidation data: unavailable. Public contract data refreshes about every 30 seconds. Every crypto setup shows a conditional 1×–10× margin plan using the same risk-sized position and the more conservative published margin window. Account eligibility, futures candle confirmation and liquidation levels remain unverified.</p><p class="note amber">Higher leverage does not increase setup confidence. A planning allocation becomes available only when the setup and data satisfy the planner’s rules; no order is sent.</p></div></section>';}
