function signalGuide(){return `<details class="panel signal-guide" aria-label="How to read signal radar"><summary>How to read a setup</summary><div class="signal-guide-grid"><div><h4>Strategy · the price pattern</h4><p><b>34 EMA:</b> cross or return to the 34-candle exponential moving average.<br><b>Momentum:</b> break out of a recent price range.<br><b>ORB:</b> break the first 5- or 15-minute opening range.<br><b>VWAP:</b> pull back to the session’s volume-weighted average price.<br><b>Retest / retrace:</b> revisit a level after crossing it.</p></div><div><h4>Status · is the setup still usable?</h4><dl><div><dt class="live">Confirmed</dt><dd>The closed-candle pattern completed. Optional checks may still fail; review Top Pick status.</dd></div><div><dt class="cyan">Setup forming</dt><dd>Waiting for pattern confirmation.</dd></div><div><dt>Watch</dt><dd>One or more entry checks unmet.</dd></div><div><dt class="amber">Setup expired</dt><dd>The configured entry window ended; its length depends on the candle interval and entry-window setting.</dd><dt class="amber">Quote delayed / unavailable</dt><dd>Price is older than your freshness limit, or no usable quote arrived. Live data unavailable means candle history or the feed needs recovery.</dd></div><div><dt class="red">Invalidated</dt><dd>Price crossed the setup’s stop level.</dd></div><div><dt class="amber">Risk blocked</dt><dd>Risk limits or entry schedule prevent entry.</dd></div></dl></div><div><h4>Estimated profit chance · measured outcomes</h4><p>Profit estimates use earlier replay and measured paper outcomes, with strategy and factor adjustments when enough model data exists. A setup score is a separate checklist grade; confirmation and estimated profitability are independent.</p><p>A confirmed pattern can have weak odds. Top Picks add quality and measured-edge checks; stale, conflicted and blocked setups remain ineligible. Options results are separate from the underlying setup.</p><p class="signal-guide-tip">Bullish = upward setup · Bearish = downward setup. 1m / 3m = candle length. Trending = sustained direction; choppy = back-and-forth; transitional = mixed conditions. Select a row for its exact checks.</p></div></div></details>`;}
function optionPlanRow(s){if(s.conflicted)return '';const p=s.optionPlan;if(!p)return '';return '<div class="signal-leverage option-signal-plan"><strong>'+esc(p.type)+' idea</strong><span>Expiry: '+esc(p.expiration||'Needs a current option chain')+'</span><span>Premium: '+(p.contract?money(p.contract.ask)+' ask / share':'Waiting for a fresh contract quote')+'</span><small>'+esc(p.reality?.blocked?p.reality.reason:p.label)+'</small></div>';}

function optionPlanDetail(s){const p=s.optionPlan;if(!p)return '';const r=p.reality;return '<section class="option-plan-detail" id="option-plan-detail" data-option-signal="'+esc(s.id)+'"><h2>'+esc(p.type)+' option idea</h2><p>Suggested expiry: <b>'+esc(p.expiration||'Waiting for listed dates')+'</b>. A bullish stock setup maps to a call idea; a bearish setup maps to a put idea. This does not predict option profit.</p><p>'+esc(p.label)+'</p>'+(p.contract?'<p>Candidate strike '+money(p.contract.strike)+' · ask '+money(p.contract.ask)+' · debit '+money(p.contract.debit)+'.</p>':'<p>'+esc(p.availability?.reason||'No matching contract currently passes the entry filters.')+'</p>')+(r?.available?'<div class="notice '+(r.blocked?'':'info')+'"><b>'+esc(r.reason)+'</b><p>Estimated option P&L at underlying target: '+money(r.target.pnl)+' / at underlying stop: '+money(r.stop.pnl)+' per contract. Round-trip spread '+money(r.spreadCost)+' ('+num(r.spreadOfRisk*100,1)+'% of planned risk).</p><p class="note">'+esc(r.label)+'</p></div>':'<p class="note">Option P&L estimate is unavailable until a matching contract passes the quote and liquidity checks.</p>')+'<p class="note">Underlying and option outcomes are recorded separately. An underlying stop cannot cap an option loss.</p><div class="form-actions"><button data-evidence-signal="'+esc(s.id)+'">Check news & dates</button>'+(p.expiration?'<button data-plan-contracts="'+esc(s.id)+'">Inspect contracts</button>':'')+'</div></section>';}

