function betaSettings(s){const check=(name,label,value)=>'<label class="check"><input type="checkbox" name="'+esc(name)+'" '+(value?'checked':'')+'>'+esc(label)+'</label>';return '<section class="panel"><div class="panel-head"><h2>Strategies & local research</h2></div><div class="panel-body form-grid">'+field('Crypto signal frames (minutes)','cryptoFrames',s.cryptoFrames.join(', '),'text','60, 1440 default; 5 and 15 optional')+cryptoVenueFields(s,select)+select('Forward-test target','forwardExitMode',[['1.5R','1.5R'],['2R','2R']],s.forwardExitMode||'2R')+select('Historical replay entry model','entryOrder',[['market','Market · next bar / quote'],['limit','Limit · must trade through']],s.entryOrder)+field('Replay / earlier-cohort exit styles','exitStyles',s.exitStyles.join(', '),'text','fixed, atr-trail, swing-trail')+field('Replay trailing-stop ATR multiple','trailingATR',s.trailingATR)+check('inPlay.enabled','Include today’s stocks in play alongside the watchlist',s.inPlay.enabled)+Object.entries({minRVOL:'Opening RVOL minimum',minGap:'Opening gap threshold (%)',strongRVOL:'Strong opening RVOL',minPrice:'Minimum stock price ($)',minDailyVolume:'Average daily shares minimum',minDailyATR:'Daily ATR minimum ($)'}).map(([k,label])=>field(label,'inPlay.'+k,s.inPlay[k])).join('')+Object.entries({orbTop:'Opening-range top stocks',orbStopATR:'ORB daily ATR stop fraction',momentumThreshold:'SPY/QQQ first-half-hour return (fraction)',earningsGap:'Earnings gap threshold (%)',earningsRVOL:'Earnings volume minimum',earningsSurprise:'EPS surprise threshold (fraction)',earningsHoldDays:'Post-earnings maximum trading days',trendTrailATR:'Daily trend initial ATR stop'}).map(([k,label])=>field(label,'special.'+k,s.special[k])).join('')+check('scanner.enabled','Enable public news and movers scanner',s.scanner.enabled)+check('signalsWatchlistOnly','Only generate stock signals for my watchlist (news scanner stays broad)',s.signalsWatchlistOnly)+field('SEC User-Agent (app name and your contact email)','scanner.secUserAgent',s.scanner.secUserAgent,'text','SEC is skipped until configured')+field('Additional public RSS feeds','scanner.feeds',s.scanner.feeds.join(', '),'text','HTTPS public feeds only; comma separated')+field('Maximum recovery lookback (days)','service.catchUpDays',s.service.catchUpDays)+'<p class="note">Run JARVIS from 09:25 ET. Computation and storage are local; free public market and news feeds require internet. No paid service, cloud backend or order route is used.</p></div></section>';}
function signalControls(s){const check=(name,label,value)=>'<label class="check"><input type="checkbox" name="'+esc(name)+'" '+(value?'checked':'')+'>'+esc(label)+'</label>';return '<section class="panel"><div class="panel-head"><h2>Signals & Top Picks</h2></div><div class="panel-body form-grid">'+check('liveSignalsOnly','Live signals only · exclude delayed fallback data',s.liveSignalsOnly)+check('showInactiveSignals','Include blocked, expired, delayed, invalidated and conflicted setups in Signal Radar',s.showInactiveSignals)+check('strictContinuations','Use stricter EMA, VWAP and breakout continuation triggers',s.strictContinuations)+select('Confirmation style','qualificationMode',[['balanced','Pattern confirmation · optional checks stay visible'],['strict','Strict · require every enabled quality check']],s.qualificationMode)+check('allowOneMinute','Allow one-minute stock research signals',s.allowOneMinute)+field('Entry window (timeframe bars)','callWindowBars',s.callWindowBars)+field('Stock price freshness allowance (seconds)','stockStaleSeconds',s.stockStaleSeconds)+select('Public stock candles · research / fallback preference','sourcePreference',[['cnbc','CNBC first, Yahoo fallback'],['yahoo','Yahoo first, CNBC fallback']],s.sourcePreference)+check('publicOptionResearch','Show Cboe delayed option research candidates',s.publicOptionResearch)+field('Top Pick minimum setup score','topPicks.minScore',s.topPicks.minScore)+field('Top Pick minimum profit probability (0–1)','topPicks.minProbability',s.topPicks.minProbability)+field('Historical fallback minimum average R','topPicks.minExpectedR',s.topPicks.minExpectedR)+'<p class="note">Confirmed means a closed-candle pattern completed. Optional failures remain visible without vetoing Top Picks. Model estimates use your probability threshold; without a model, historical results veto after 15 matching outcomes if average R is not positive. Uncalibrated picks can qualify. Validation is reported separately. Delayed option research is never treated as a fresh quote.</p></div></section>';}
function advancedSettings(s){
 const check=(name,label,value)=>'<label class="check"><input type="checkbox" name="'+esc(name)+'" '+(value?'checked':'')+'>'+esc(label)+'</label>';
 return signalControls(s)+betaSettings(s)+'<section class="panel"><div class="panel-head"><h2>Individual strategy controls</h2></div><div class="panel-body"><p class="note">Each saved parameter change starts a new results cohort. Old cohorts stay in the ledger. Parameters are never fitted to validation outcomes.</p>'+Object.entries(state.rules).map(([id,r])=>{const p=strategyParams(s,id);return '<details class="strategy-controls"><summary>'+esc(r.name)+'</summary><div class="form-grid">'+['stocks','crypto'].map(m=>field(m+' evaluation frames','strategyMarketFrames.'+m+'.'+id,strategyFramesForMarket(s,id,m).join(', '),'text',m==='stocks'?'1 (when enabled), 3, 5, 15, 1440; blank disables':'5, 15, 60, 1440; blank disables')).join('')+Object.entries(PARAMS).map(([k,d])=>d.tristate?select(d.label,'param.'+id+'.'+k,[['','Use shared setting'],['true','On'],['false','Off']],p[k]===null?'':String(p[k])):d.boolean?check('param.'+id+'.'+k,d.label,p[k]):d.choices?select(d.label,'param.'+id+'.'+k,d.choices.map(v=>[v,v+' minutes']),p[k]):field(d.label,'param.'+id+'.'+k,p[k],'number','','min="'+d.min+'" max="'+d.max+'" step="'+(d.integer?'1':'any')+'"')).join('')+'</div></details>';}).join('')+'</div></section><section class="panel"><div class="panel-head"><h2>Profit model & daily review</h2></div><div class="panel-body form-grid">'+check('includeFallbackTraining','Allow unofficial fallback data in model training',s.includeFallbackTraining)+check('dailyReview.enabled','Run daily history refresh and model review',s.dailyReview.enabled)+field('Fine-grained history days (1–28)','dailyReview.historyDays',s.dailyReview.historyDays)+field('Longer history months (1–24)','dailyReview.months',s.dailyReview.months)+field('Suspend strategy beyond drawdown (R)','maxStrategyDrawdownR',s.maxStrategyDrawdownR)+'<p class="note">Cards use outcome-based strategy estimates, with no 200-trade display wait. Small samples are labeled preliminary; missing outcomes are shown honestly. Measured profit models continue learning and validating on separate later outcomes in the background. Strategy settings start a new cohort. Auto paper simulations are shown separately from the manual journal.</p></div></section><section class="panel"><div class="panel-head"><h2>Top Pick notifications</h2></div><div class="panel-body">'+check('alerts.enabled','Notify me about new Top Picks only',s.alerts.enabled)+check('alerts.sound','Play alert tones',s.alerts.sound)+check('alerts.flash','Highlight cards and flash tab title',s.alerts.flash)+check('alerts.desktop','Use desktop notifications when browser permission is granted',s.alerts.desktop)+'<div class="form-grid">'+select('Tone','alerts.soundChoice',[['chime','Chime'],['bell','Bell'],['pulse','Pulse']],s.alerts.soundChoice)+field('Volume (0–1)','alerts.volume',s.alerts.volume)+field('Maximum alerts per hour','alerts.maxPerHour',s.alerts.maxPerHour)+field('Symbol cooldown (seconds)','alerts.cooldownSeconds',s.alerts.cooldownSeconds)+field('Quiet hours, local zone','alerts.quietHours',s.alerts.quietHours.join(', '),'text','HH:MM-HH:MM, comma separated; overnight ranges allowed')+'</div><button type="button" data-action="test-alert">Enable / test browser sound</button><p class="note">Sound requires a click in this tab. Test plays a preview. Automatic notifications are for new Top Picks only, using the same rules and estimated win percent shown on the cards. Quiet hours, symbol cooldown and hourly limits still apply. Existing picks do not alert again on page load. Desktop popups also need browser permission.</p></div></section><section class="panel"><div class="panel-head"><h2>No-trade events & options costs</h2></div><div class="panel-body"><div class="form-grid">'+['CPI','FOMC'].map(k=>select(k+' block','eventBlocks.'+k+'.mode',[['day','Full event day'],['window','Minutes around release']],s.eventBlocks[k].mode)+field(k+' minutes before/after','eventBlocks.'+k+'.minutes',s.eventBlocks[k].minutes)).join('')+field('Earnings blackout days before/after','eventBlocks.earningsDays',s.eventBlocks.earningsDays)+field('Maximum option spread / planned risk (0–1)','maxSpreadOfRisk',s.maxSpreadOfRisk)+'</div>'+check('eventBlocks.firstFiveMinutes','Block the first five minutes after the stock open',s.eventBlocks.firstFiveMinutes)+'<p class="note">These extend the existing event filter. The event filter toggle still applies. FOMC window mode uses 14:00 ET on the official decision date; unavailable calendar coverage stays visible.</p></div></section>';
}
function readAdvancedSettings(s,fd,get,number){
 s.liveSignalsOnly=fd.has('liveSignalsOnly');s.showInactiveSignals=fd.has('showInactiveSignals');s.strictContinuations=fd.has('strictContinuations');s.qualificationMode=get('qualificationMode');s.allowOneMinute=fd.has('allowOneMinute');s.callWindowBars=number('callWindowBars');s.stockStaleSeconds=number('stockStaleSeconds');s.sourcePreference=get('sourcePreference');s.publicOptionResearch=fd.has('publicOptionResearch');s.topPicks={};for(const k of ['minScore','minProbability','minExpectedR'])s.topPicks[k]=number('topPicks.'+k);
 s.cryptoFrames=get('cryptoFrames').split(',').map(x=>Number(x.trim())).filter(Number.isFinite);s.cryptoFrame=s.cryptoFrames[0];s.cryptoVenue=get('cryptoVenue');s.forwardExitMode=get('forwardExitMode');s.entryOrder=get('entryOrder');s.exitStyles=get('exitStyles').split(',').map(x=>x.trim()).filter(Boolean);s.trailingATR=number('trailingATR');s.inPlay={enabled:fd.has('inPlay.enabled')};for(const k of ['minRVOL','minGap','strongRVOL','minPrice','minDailyVolume','minDailyATR'])s.inPlay[k]=number('inPlay.'+k);s.special={};for(const k of ['orbTop','orbStopATR','momentumThreshold','earningsGap','earningsRVOL','earningsSurprise','earningsHoldDays','trendTrailATR'])s.special[k]=number('special.'+k);s.signalsWatchlistOnly=fd.has('signalsWatchlistOnly');s.scanner={enabled:fd.has('scanner.enabled'),secUserAgent:get('scanner.secUserAgent'),feeds:get('scanner.feeds').split(',').map(x=>x.trim()).filter(Boolean)};s.service={catchUpDays:number('service.catchUpDays')};
 s.strategyParams={};s.strategyMarketFrames={stocks:{},crypto:{}};
 for(const id of Object.keys(state.rules)){s.strategyParams[id]={};for(const [k,d]of Object.entries(PARAMS))s.strategyParams[id][k]=d.tristate?(get('param.'+id+'.'+k)===''?null:get('param.'+id+'.'+k)==='true'):d.boolean?fd.has('param.'+id+'.'+k):number('param.'+id+'.'+k);for(const m of ['stocks','crypto'])s.strategyMarketFrames[m][id]=get('strategyMarketFrames.'+m+'.'+id).split(',').map(x=>x.trim()).filter(Boolean).map(Number);}
 if(!s.allowOneMinute){s.stockFrames=s.stockFrames.filter(tf=>tf!==1);if(!s.stockFrames.length)s.stockFrames=[3];for(const frames of Object.values(s.strategyMarketFrames.stocks))while(frames.includes(1))frames.splice(frames.indexOf(1),1);for(const frames of Object.values(s.strategyFrames))while(frames.includes(1))frames.splice(frames.indexOf(1),1);}
 s.includeFallbackTraining=fd.has('includeFallbackTraining');s.dailyReview={enabled:fd.has('dailyReview.enabled'),hourET:s.dailyReview.hourET,historyDays:number('dailyReview.historyDays'),months:number('dailyReview.months')};
 s.alerts={...s.alerts};for(const k of ['enabled','sound','flash','desktop'])s.alerts[k]=fd.has('alerts.'+k);for(const k of ['volume','cooldownSeconds','maxPerHour'])s.alerts[k]=number('alerts.'+k);s.alerts.soundChoice=get('alerts.soundChoice');s.alerts.quietHours=get('alerts.quietHours').split(',').map(x=>x.trim()).filter(Boolean);
 for(const k of ['maxStrategyDrawdownR','maxSpreadOfRisk'])s[k]=number(k);
 s.eventBlocks={earningsDays:number('eventBlocks.earningsDays'),firstFiveMinutes:fd.has('eventBlocks.firstFiveMinutes')};for(const k of ['CPI','FOMC'])s.eventBlocks[k]={mode:get('eventBlocks.'+k+'.mode'),minutes:number('eventBlocks.'+k+'.minutes')};
}
function historyPanel(){const h=state.status.publicMarket;return '<section class="panel" id="history-panel"><div class="panel-head"><h2>Downloaded history</h2><button data-action="refresh-history" '+(h?.busy?'disabled':'')+'>'+(h?.busy?'Downloading…':'Refresh history')+'</button></div><div class="panel-body"><p class="note">Stored separately by symbol, timeframe and provider. Fine intraday history depends on provider limits; daily and 15-minute history cover longer periods. Gaps are recorded and never filled with invented candles.</p><div class="table-wrap"><table><thead><tr><th>Symbol</th><th>Frame</th><th>Source</th><th>Bars</th><th>Gaps</th><th>Coverage</th></tr></thead><tbody>'+historyDatasets.map(d=>'<tr><td>'+esc(d.symbol)+'</td><td>'+d.base/60+'m</td><td>'+esc(d.source)+(d.fallback?' · fallback':'')+'</td><td>'+d.count+'</td><td>'+(d.gaps?.length||0)+'</td><td>'+(d.partial?'Partial download':'Retrieved')+'<div class="note">'+esc(d.errors?.[0]?.error||'')+'</div></td></tr>').join('')+'</tbody></table></div></div></section>';}
async function loadHistory(){historyLast=Date.now();try{const result=await api('/api/history');const oldChoice=$('[name=historyDataset]')?.value,oldDataset=oldChoice?historyDatasets[Number(oldChoice)]:null;historyDatasets=result.datasets;const picker=$('[name=historyDataset]');if(picker&&document.activeElement!==picker){const chosen=oldDataset?historyDatasets.findIndex(d=>d.symbol===oldDataset.symbol&&d.base===oldDataset.base&&d.source===oldDataset.source):-1;picker.innerHTML='<option value="">Current source candles</option>'+historyDatasets.map((d,i)=>'<option value="'+i+'">'+esc(d.symbol+' · '+d.base/60+'m · '+d.source+' · '+d.count+' bars')+'</option>').join('');picker.value=chosen>=0?String(chosen):'';}if($('#history-panel')){$('#history-panel').outerHTML=historyPanel();enhancePanels($('#content'),{page,preferences:panelView});applyWorkspaceLayout(document,workspaceView);}}catch(e){toast(e.message,true);}}
async function playAlert(test=false){if(!test&&!state.settings.alerts.sound)return;if(test){alertAudio??=new (window.AudioContext||window.webkitAudioContext)();await alertAudio.resume();}if(!alertAudio||alertAudio.state!=='running')return;const s=state.settings.alerts,notes=s.soundChoice==='bell'?[880,1320]:s.soundChoice==='pulse'?[660,660,660]:[660,880,1100];for(let i=0;i<notes.length;i++){const oscillator=alertAudio.createOscillator(),gain=alertAudio.createGain(),t=alertAudio.currentTime+i*.18;oscillator.frequency.value=notes[i];gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(s.volume*.3,t+.02);gain.gain.exponentialRampToValueAtTime(.0001,t+.3);oscillator.connect(gain);gain.connect(alertAudio.destination);oscillator.start(t);oscillator.stop(t+.32);}}
function flashAlert(s){if(!state.settings.alerts.flash)return;if(s){flashingSignals.set(s.id,Date.now()+6500);for(const el of document.querySelectorAll('[data-signal]'))if(el.dataset.signal===s.id)el.classList.add('high-quality-alert');}document.body.classList.add('browser-alert');setTimeout(()=>document.body.classList.remove('browser-alert'),6500);clearInterval(titleTimer);let count=0;titleTimer=setInterval(()=>{document.title=count++%2?'JARVIS':'● '+(s?.symbol||'TEST')+' · JARVIS alert';if(count>=12){clearInterval(titleTimer);document.title='JARVIS';}},550);}
async function notifyHighQualitySignals(){for(const s of alertTracker.update(currentTopPicks(),state.settings,Date.now())){let result;try{result=await api('/api/alerts',{signalId:s.id});}catch(e){alertTracker.retry(s.id);toast(e.message,true);continue;}if(result.duplicate)continue;const entry={...topPickAlert(s,result.alert.createdAt),...result.alert,category:notificationCategory(s),seen:false,example:false};addNotification(entry);flashAlert(s);try{await playAlert();}catch{}if(state.settings.alerts.desktop&&'Notification' in window&&Notification.permission==='granted')try{new Notification(notificationCategory(s),{body:entry.title+' · '+entry.message,tag:s.id});}catch{}}ensureNotificationInbox();}
function journalReviewView(rows){return '<p class="note">Actual trades use the fill prices and net P&L you entered. System results use passive underlying observations after costs. R differences are hypothetical opportunities, not cash losses; option comparisons use separately measured option bids/asks and full premium risk.</p><div class="table-wrap"><table><thead><tr><th>Symbol</th><th>Decision</th><th>Adverse fill / unit</th><th>Your R / system R</th><th>Skipped winner R / modeled P&L</th><th>Early-exit gap R / modeled P&L</th><th>Rule breaks</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.symbol)+'</td><td>'+esc(r.decision)+'</td><td>'+money(r.slippagePerUnit)+'</td><td>'+num(r.actualR,3)+' / '+num(r.systemR,3)+'</td><td>'+num(r.skippedWinnerR,3)+' / '+money(r.skippedWinnerPnL)+'<div class="note">'+esc(r.cashBasis)+'</div></td><td>'+num(r.earlyExitGapR,3)+' / '+money(r.earlyExitGapPnL)+'</td><td>'+r.ruleBreaks.map(esc).join('; ')+'</td></tr>').join('')+'</tbody></table></div>';}
