let sidebarDrag=null,suppressSidebarClick=false;
document.addEventListener('pointerdown',event=>{const el=event.target.closest?.('#workspace-nav [data-page]');if(!el||event.button!==0||event.pointerType==='touch')return;sidebarDrag={id:el.dataset.page,x:event.clientX,y:event.clientY,el,active:false};});
document.addEventListener('pointermove',event=>{if(!sidebarDrag)return;if(!sidebarDrag.active&&Math.hypot(event.clientX-sidebarDrag.x,event.clientY-sidebarDrag.y)>8){sidebarDrag.active=true;sidebarDragging=true;sidebarDrag.el.classList.add('is-dragging');sidebarDrag.el.setPointerCapture?.(event.pointerId);}if(sidebarDrag.active){event.preventDefault();document.body.classList.add('sidebar-is-dragging');}});
document.addEventListener('pointerup',event=>{const drag=sidebarDrag;sidebarDrag=null;sidebarDragging=false;document.body.classList.remove('sidebar-is-dragging');drag?.el.classList.remove('is-dragging');if(!drag?.active)return;suppressSidebarClick=true;const target=document.elementFromPoint(event.clientX,event.clientY),group=target?.closest('#workspace-nav .sidebar-group');if(group){saveSidebar(moveSection(sidebarView.get(),drag.id,group.dataset.navGroup,target.closest('[data-page]')?.dataset.page));}setTimeout(()=>suppressSidebarClick=false,0);});
document.addEventListener('pointercancel',()=>{sidebarDrag?.el.classList.remove('is-dragging');sidebarDrag=null;sidebarDragging=false;document.body.classList.remove('sidebar-is-dragging');});
document.addEventListener('click',event=>{if(suppressSidebarClick&&event.target.closest?.('#workspace-nav')){event.preventDefault();event.stopImmediatePropagation();}},true);


